use serde_json::{json,Value};
use std::rc::Rc;
use kfc_kfc_alpha::kfc::{opcr::{OpcRelation::OpcRelation,OpcTargetMode::OpcTargetMode},opcw::{native::RelationRef,OpcwRelationships::OpcwRelationships},xpxml::writer::{r#impl::MemoryXmlWriter::MemoryXmlWriter,XmlWriter::XmlWriter}};
fn panic_name(e:Box<dyn std::any::Any+Send>)->String{let message=e.downcast_ref::<String>().cloned().or_else(||e.downcast_ref::<&str>().map(|s|s.to_string())).unwrap_or_default();for name in ["NullPointerException","IllegalArgumentException"]{if message.contains(name){return name.into();}}panic!("unexpected native panic {message}")}
#[test]
fn original_android_nullable_relation_and_xml_facade(){
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/relations-r0b29");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut relations=vec![];
    for row in java["relations"].as_array().unwrap(){let input=&row["input"];let rel=OpcRelation::OpcRelation(input[0].as_str(),input[1].as_str(),input[2].as_str());let mut indices=vec![];for index in row["indices"].as_array().unwrap(){let i=index["input"].as_i64().unwrap()as i32;let mut actual=json!({"input":i});match std::panic::catch_unwind(||rel.getPartName__index(i)){Ok(v)=>actual["out"]=json!(v),Err(e)=>actual["exception"]=json!(panic_name(e))};assert_eq!(actual,*index);indices.push(actual);}let actual=json!({"input":input,"content":rel.getContentType(),"type":rel.getRelsType(),"part":rel.getPartName(),"text":rel.toString(),"indices":indices});assert_eq!(actual,*row);relations.push(actual);}
    let mut attributes=vec![];for row in java["attributes"].as_array().unwrap(){let input=&row["input"];let mut writer=MemoryXmlWriter::new();writer.startElement("e");writer.addAttr__nsNullable(input[0].as_str(),input[1].as_str(),input[2].as_str());writer.endElement("e");let actual=json!({"input":input,"out":writer.getString()});assert_eq!(actual,*row);attributes.push(actual);}
    let mut writes=vec![];for row in java["writes"].as_array().unwrap(){let input=&row["input"];let rel=RelationRef::Local(Rc::new(OpcRelation::OpcRelation(None::<&str>,input["type"].as_str(),input["part"].as_str())));let mut rels=OpcwRelationships::OpcwRelationships(None,"xl/book.xml".into());let rel=rels.addRelationship__5(rel,input["target"].as_str().map(str::to_string),Some(if input["mode"]=="EXTERNAL"{OpcTargetMode::EXTERNAL}else{OpcTargetMode::INTERNAL}),input["encode"].as_bool().unwrap());let mut writer=MemoryXmlWriter::new();let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||rel.borrow().write(&mut writer,"xl/book.xml").unwrap()));let result=result.map_or_else(panic_name,|_|"ok".into());let actual=json!({"input":input,"result":result,"out":writer.getString()});assert_eq!(actual,*row);writes.push(actual);}
    let actual=json!({"relations":relations,"attributes":attributes,"writes":writes});let mut expected=java;expected.as_object_mut().unwrap().remove("strategies");assert_eq!(actual,expected);std::fs::write(p.join("rust-nullable.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
fn descriptor(r:&OpcRelation)->Value{json!({"content":r.getContentType(),"type":r.getRelsType(),"part":r.getPartName(),"text":r.toString()})}
fn identity(pool:&mut Vec<RelationRef>,r:RelationRef)->usize{if let Some(id)=pool.iter().position(|old|std::ptr::eq(&**old,&*r)){id}else{let id=pool.len();pool.push(r);id}}
#[test]
fn original_android_xls_clip_strategy_and_object_identity(){
    use kfc_kfc_alpha::kfc::{ooxfr::OxfXlRelations::{self,OxfXlRelations as X},clipr::XlsClipRelationsImpl::XlsClipRelationsImpl};
    let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/relations-r0b29");let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let expected=&java["strategies"];let mut actual=json!({});let mut pool=vec![];
    actual["beforeInit"]=json!(std::panic::catch_unwind(||X::imagePng()).map_or_else(panic_name,|_|"ok".into()));let _=X::OxfXlRelations();actual["afterConstructor"]=json!(std::panic::catch_unwind(||X::imagePng()).map_or_else(panic_name,|_|"ok".into()));
    let mut constants=vec![];for row in expected["constants"].as_array().unwrap(){let name=row["name"].as_str().unwrap();let r=OxfXlRelations::constant(name);let id=identity(&mut pool,RelationRef::Static(r));let a=json!({"name":name,"id":id,"value":descriptor(r)});assert_eq!(a,*row);constants.push(a);}actual["constants"]=json!(constants);
    let mut stages=vec![];for stage in expected["stages"].as_array().unwrap(){let mode=stage["mode"].as_i64().unwrap();if mode==0{X::setXlsRelation();}else{X::setClipRelation();}let mut values=vec![];for row in stage["values"].as_array().unwrap(){let name=row["name"].as_str().unwrap();let getter:fn()->RelationRef=match name{"chart"=>X::chart,"chartColor"=>X::chartColor,"chartStyle"=>X::chartStyle,"chartExternalSrc"=>X::chartExternalSrc,"diagramQuickStyle"=>X::diagramQuickStyle,"diagramData"=>X::diagramData,"diagramLayout"=>X::diagramLayout,"diagramColors"=>X::diagramColors,"diagramDrawing"=>X::diagramDrawing,"oleObjectDocx"=>X::oleObjectDocx,"oleObjectDoc"=>X::oleObjectDoc,"oleObjectDocm"=>X::oleObjectDocm,"imageEmf"=>X::imageEmf,"imageWmf"=>X::imageWmf,"imagePict"=>X::imagePict,"imageJpeg"=>X::imageJpeg,"imagePng"=>X::imagePng,"imageDib"=>X::imageDib,"imageGif"=>X::imageGif,"imageBmp"=>X::imageBmp,"wdp"=>X::wdp,"theme"=>X::theme,"themeOverride"=>X::themeOverride,"ink"=>X::ink,"oleObjectBin"=>X::oleObjectBin,_=>panic!("unknown getter")};let first=getter();let again=getter();let same=std::ptr::eq(&*first,&*again);let value=descriptor(&first);let id=identity(&mut pool,first);let a=json!({"name":name,"id":id,"same":same,"value":value});assert_eq!(a,*row,"mode {mode}, method {name}");values.push(a);}stages.push(json!({"mode":mode,"values":values}));}actual["stages"]=json!(stages);
    let mut a=XlsClipRelationsImpl::XlsClipRelationsImpl();let mut b=XlsClipRelationsImpl::XlsClipRelationsImpl();let drawing=a.drawing();actual["drawing"]=json!({"same":std::ptr::eq(&*drawing,&*a.drawing()),"different":!std::ptr::eq(&*drawing,&*b.drawing()),"value":descriptor(&drawing)});X::setXlsRelation();assert_eq!(actual,*expected);std::fs::write(p.join("rust-strategies.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();
}
